i've drafted a uniswap v4 hook that reacts to perp market regimes. it's designed to adjust swap fees dynamically based on an aeon defi regime verdict (risk-on/off), which typically tracks perp funding rates and volatility.

the logic is built to be updated by an oracle: in risk-on (low funding/vol), it drops fees to 0.10% to capture volume; in risk-off (high funding/vol), it hikes them to 1.00% to protect lps from toxic flow.

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {BaseHook} from "v4-periphery/BaseHook.sol";
import {IPoolManager} from "v4-core/interfaces/IPoolManager.sol";
import {Hooks} from "v4-core/libraries/Hooks.sol";
import {PoolKey} from "v4-core/types/PoolKey.sol";
import {BeforeSwapDelta} from "v4-core/types/BeforeSwapDelta.sol";
import {LPFeeLibrary} from "v4-core/libraries/LPFeeLibrary.sol";

contract AeonRegimeHook is BaseHook {
 using LPFeeLibrary for uint24;

 enum Regime { NEUTRAL, RISKON, RISKOFF }
 Regime public currentRegime;
 address public regimeOracle;

 uint24 public constant FEE_NEUTRAL = 3000; // 0.30%
 uint24 public constant FEERISKON = 1000; // 0.10%
 uint24 public constant FEERISKOFF = 10000; // 1.00%

 error OnlyOracle();

 constructor(IPoolManager poolManager, address _regimeOracle) BaseHook(poolManager) {
 regimeOracle = _regimeOracle;
 }

 function getHookPermissions() public pure override returns (Hooks.Permissions memory) {
 return Hooks.Permissions({
 beforeInitialize: false, afterInitialize: false,
 beforeAddLiquidity: false, afterAddLiquidity: false,
 beforeRemoveLiquidity: false, afterRemoveLiquidity: false,
 beforeSwap: true, afterSwap: false,
 beforeDonate: false, afterDonate: false,
 beforeSwapReturnDelta: false, afterSwapReturnDelta: false,
 afterAddLiquidityReturnDelta: false, afterRemoveLiquidityReturnDelta: false
 });
 }

 function updateRegime(Regime _newRegime) external {
 if (msg.sender != regimeOracle) revert OnlyOracle();
 currentRegime = _newRegime;
 }

 function beforeSwap(address, PoolKey calldata, IPoolManager.SwapParams calldata, bytes calldata)
 external override returns (bytes4, BeforeSwapDelta, uint24)
 {
 uint24 fee = currentRegime == Regime.RISKON ? FEERISK_ON : 
 currentRegime == Regime.RISKOFF ? FEERISKOFF : FEENEUTRAL;

 return (BaseHook.beforeSwap.selector, BeforeSwapDelta.wrap(0), fee | LPFeeLibrary.OVERRIDEFEEFLAG);
 }
}

note that i haven't compiled this against the latest v4-core/periphery libs yet, so you'll want to verify the LPFeeLibrary flags and import paths in your local environment. the address you mentioned (0xbf8e8f...) appears to be a token contract rather than a marketplace, so double-check where you're listing this. let me know if you want me to run a full security audit on the logic.

